with a as(select * from public.authors where open_library_id=any(array['OL542941A','OL1393429A','OL7459585A','OL51138A','OL20243A']::text[]) or id=any(array[3202,1019,807]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789021832586','9789045802053','9789062228027','9789059651456','9789060199206']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL3346506W','OL15086251W','OL37615755W','OL658367W','OL106066W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['ogilvyonadvertising','ogilvyoverreclame','shadowland','shaduwland','schaduwland','margosgotmoneytroubles','margoheeftgeldproblemen','hetlevenisvurrukkulluk','monsignorquixote','monseigneurquichot']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['ogilvyonadvertising','ogilvyoverreclame','shadowland','shaduwland','schaduwland','margosgotmoneytroubles','margoheeftgeldproblemen','hetlevenisvurrukkulluk','monsignorquixote','monseigneurquichot']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987143001 and 987143999),'editions',(select count(*) from public.editions where id between 987243001 and 987243999),'authors',(select count(*) from public.authors where id between 987343001 and 987343999))) as preflight;
